"""Compile the files generated by `tools/port.py` and choose a compiling proof for each theorem.

Usage: python3 -I tools/portcheck.py [--force] [MODULE ...]

For each generated module, in import order (or only the given ones), the script regenerates the
file, builds it with `lake build`, and maps every error to the theorem whose block contains it.
Each failing theorem moves to its next candidate proof; a theorem with no candidate left becomes
`sorry` (the error of its first candidate is kept for the `-- REVIEW` comment). The loop ends when
the module builds. Choices are recorded in `tools/data/review.json`, which `port.py` reads, so
`python3 -I tools/port.py lemmas` alone reproduces the files.

An error outside any theorem, or in a theorem that is already `sorry`, cannot be fixed by choosing
a proof: the script stops and prints it (that is a statement or command that does not elaborate,
which must never be "fixed" by changing the statement).

It refuses to touch a file that differs from the generated text (a proof fixed by hand in Wave 2)
unless `--force` is given. Run one build at a time: the script calls `lake build` sequentially.
"""
import json
import os
import re
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, HERE)

import port   # noqa: E402
import split  # noqa: E402

MODULES = ([f'OAMap.HashMap.Lemmas.{f}' for (f, *_rest) in split.HASHMAP_CUTS] +
           ['OAMap.HashMap.Lemmas', 'OAMap.HashSet.Basic', 'OAMap.HashSet.DecidableEquiv',
            'OAMap.HashSet.Lemmas'])

ERR = re.compile(r'^error: (?P<file>[^:\n]+\.lean):(?P<line>\d+):(?P<col>\d+): (?P<msg>.*)$', re.M)


def path_of(mod):
    return mod.replace('.', '/') + '.lean'


def theorem_spans(text, prefix):
    """(first line, last line, full Std name, is_sorry) of every theorem block of a generated file."""
    spans = []
    ns = []
    for b in split.parse(text):
        if b.kind == 'namespace':
            ns.append(b.name)
        elif b.kind == 'end' and ns and b.name == ns[-1]:
            ns.pop()
        elif b.kind == 'theorem':
            inner = [x for x in ns if x not in ('OAMap.HashMap', 'OAMap.HashSet')]
            full = '.'.join([prefix] + inner + [b.name])
            spans.append((b.start, b.end, full, '\n  sorry' in b.text and '-- REVIEW' in b.text))
    return spans


def build(mod):
    r = subprocess.run(['lake', 'build', mod], cwd=ROOT, capture_output=True, text=True)
    return r.returncode, r.stdout + r.stderr


def first_line(msg):
    return msg.strip().split('\n')[0][:300]


def check(mod, std, review):
    path = path_of(mod)
    prefix = 'Std.HashSet' if 'HashSet' in mod else 'Std.HashMap'
    base = None
    for it in range(12):
        port_files, log = port.generate(std, base=base, force=FORCE)
        if path in port.generate.skipped:
            print(f'portcheck: {mod}: {path} differs from the generated text (edited by hand?); '
                  'pass --force to regenerate it')
            sys.exit(1)
        base = port_files
        text = port_files[path]
        code, out = build(mod)
        errs = [m for m in ERR.finditer(out) if m.group('file').endswith(path)]
        other = [m for m in ERR.finditer(out) if not m.group('file').endswith(path)]
        if other:
            print(f'portcheck: {mod}: errors in a dependency:')
            for m in other[:10]:
                print('  ', m.group(0))
            sys.exit(1)
        if code == 0 and not errs:
            n_sorry = sum(1 for s in theorem_spans(text, prefix) if s[3])
            print(f'portcheck: {mod}: ok after {it} rounds ({n_sorry} REVIEW)')
            return
        if not errs:
            print(f'portcheck: {mod}: build failed without a located error:\n{out[-3000:]}')
            sys.exit(1)
        spans = theorem_spans(text, prefix)
        failing = {}
        for m in errs:
            line = int(m.group('line'))
            span = next((s for s in spans if s[0] <= line <= s[1]), None)
            # the message: the error line plus its continuation up to the next `error:`/`warning:`
            start = m.end()
            nxt = re.search(r'^(error|warning|info|✖|✔|⚠|trace): ', out[start:], re.M)
            msg = m.group('msg') + (out[start:start + nxt.start()] if nxt else '')
            if span is None or span[3]:
                print(f'portcheck: {mod}: unfixable error at {path}:{line}:')
                print('  ' + msg.strip().replace('\n', '\n  ')[:2000])
                if span:
                    print(f'  (in {span[2]}, already sorry)')
                sys.exit(1)
            failing.setdefault(span[2], msg)
        for full, msg in failing.items():
            rv = review.get(full, {})
            choice = rv.get('choice', 0)
            ncand = len(log.get(full, {}).get('candidates', []))
            if choice == 0:
                rv['error'] = first_line(msg)
            if isinstance(choice, int):
                rv.setdefault('errors', {})[str(choice)] = first_line(msg)
            nxt_choice = choice + 1 if isinstance(choice, int) else 'sorry'
            rv['choice'] = nxt_choice if isinstance(nxt_choice, int) and nxt_choice < ncand else 'sorry'
            review[full] = rv
        save(review)
        print(f'portcheck: {mod}: round {it}: {len(failing)} failing theorems')
    print(f'portcheck: {mod}: no fixpoint after 12 rounds')
    sys.exit(1)


def save(review):
    with open(os.path.join(HERE, 'data', 'review.json'), 'w') as f:
        json.dump(dict(sorted(review.items())), f, indent=1, ensure_ascii=False)
        f.write('\n')


FORCE = False


def main():
    global FORCE
    std = split.std_data_dir()
    args = [a for a in sys.argv[1:] if a != '--force']
    FORCE = '--force' in sys.argv[1:]
    mods = args or MODULES
    review = port.load_review()
    for mod in mods:
        check(mod, std, review)
    # a theorem whose first candidate now compiles needs no entry
    print('portcheck: done')


if __name__ == '__main__':
    main()
